<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { Activity, Play, SquareStop, Settings2, X, AlertCircle } from 'lucide-vue-next'
import BaseButton from './components/base/BaseButton.vue'
import RuntimeView from './components/RuntimeView.vue'
import { call, desktop, useRuntime } from './lib/backend'
import { parseProject } from './lib/editor'
import type { Project } from './lib/model'
import { refreshAssets } from './lib/resources'
import { projectLocale,setDesignerLocale } from './lib/i18n'
const project = ref<Project>(), runtime = useRuntime(), error = ref(''), settings = ref(false), ports = ref<{ name: string; description: string }[]>([]), loading = ref(true)
async function start() { try { if (project.value) { error.value = ''; await runtime.start(project.value) } } catch (reason) { error.value = String(reason) } }
async function stop() { try { await runtime.stop() } catch (reason) { error.value = String(reason) } }
async function openSettings() { settings.value = true; try { ports.value = await call('list_serial_ports') } catch (reason) { error.value = String(reason) } }
async function savePorts() { if (!project.value) return; try { await call('save_runtime_settings', { project: project.value }); settings.value = false } catch (reason) { error.value = String(reason) } }
onMounted(async () => { try { if (!desktop) throw new Error('独立运行程序需要桌面环境。请使用 HMI Runner 启动已发布的项目。'); project.value = parseProject(JSON.stringify(await call('get_initial_project'))); document.title = project.value.name; projectLocale.value=project.value.i18n?.defaultLocale??'zh-CN'; setDesignerLocale(projectLocale.value); if (project.value.assets?.length) await refreshAssets(project.value); await start() } catch (reason) { error.value = String(reason) } finally { loading.value = false } })
onBeforeUnmount(runtime.dispose)
</script>

<template><div class="runner-shell" :class="{'project-chrome': project?.presentation?.chrome === 'project'}"><header v-if="project?.presentation?.chrome !== 'project'" class="runner-header"><div class="brand-mark"><Activity :size="20" /></div><strong data-project-text>{{ project?.name ?? 'HMI Runner' }}</strong><span class="status-pill">{{ loading ? '正在加载' : runtime.running.value ? '运行中' : '已停止' }}</span><span class="spacer" /><select v-if="project?.i18n" v-model="projectLocale" class="runtime-language" aria-label="运行语言" @change="setDesignerLocale(projectLocale)"><option v-for="locale in project.i18n.locales" :key="locale" :value="locale">{{locale}}</option></select><BaseButton :disabled="runtime.busy.value || !project" @click="runtime.running.value ? stop() : start()"><SquareStop v-if="runtime.running.value" :size="15" /><Play v-else :size="15" />{{ runtime.running.value ? '停止运行' : '开始运行' }}</BaseButton><BaseButton :disabled="runtime.running.value || !project" @click="openSettings"><Settings2 :size="16" />{{project?.backends?.length?'连接设置':'串口设置'}}</BaseButton></header><div v-if="error && project?.presentation?.chrome !== 'project'" class="runner-error" role="alert"><AlertCircle :size="18" /><span>{{ error }}</span><button class="icon-button" title="关闭错误" @click="error = ''"><X :size="15" /></button></div><RuntimeView v-if="project" :project="project" :runtime="runtime" :error="error" @error="error = $event" @retry="start" /><div v-else class="runner-loading">{{ loading ? '正在载入项目…' : '无法载入项目，请检查运行包是否完整。' }}</div><div v-if="settings && project && project.presentation?.chrome !== 'project'" class="modal-backdrop" @click.self="settings = false"><section class="help-dialog" role="dialog" aria-modal="true" aria-label="串口设置"><div class="inline-between"><h2>{{project.backends?.length?'连接设置':'串口设置'}}</h2><button class="icon-button" title="关闭" @click="settings = false"><X :size="18" /></button></div><p class="muted-copy">选择当前电脑的连接方式，设置仅保存在本机。</p><label v-for="connection in project.connections" :key="connection.id">{{ connection.name }}<select v-model="connection.port"><option v-if="!ports.some(p => p.name === connection.port) " :value="connection.port">{{ connection.port }}（当前不可用）</option><option v-for="port in ports" :key="port.name" :value="port.name">{{ port.name }} {{ port.description }}</option></select></label><label v-for="backend in project.backends??[]" :key="backend.id">{{backend.name}}<select v-model="backend.mode"><option value="simulation">模拟设备</option><option value="usb">真实 USB Printer 设备</option></select></label><p v-if="project.backends?.length" class="muted-copy">切换连接方式后，重新开始运行将创建新的设备会话。</p><BaseButton appearance="primary" @click="savePorts">保存设置</BaseButton></section></div></div></template>

<style scoped>.runtime-language{width:110px;font-size:12px}.runner-shell.project-chrome{background:#fff}.runner-shell.project-chrome>.runtime-host{padding:0}</style>
